import './groqCompat'

import {type SanityDocument, type SanityProjectionResult, type SanityQueryResult} from 'groq'

/**
 * Resolves a document using declarations from experimental Typegen.
 * Preserves the legacy lookup behavior while the SDK uses released `groq`.
 *
 * @beta
 */
export type ResolveDocument<
  TDocumentType extends string = string,
  TSchemaId extends string = string,
> = SanityDocument<TDocumentType, TSchemaId>

/**
 * Resolves a query using declarations from experimental Typegen.
 * For types generated by current Typegen, pass the result type to the hook explicitly.
 *
 * @beta
 */
export type ResolveQueryResult<
  TQuery extends string = string,
  TSchemaId extends string = string,
> = SanityQueryResult<TQuery, TSchemaId>

/**
 * Resolves a projection using declarations from experimental Typegen.
 * Selects the result by projection string, document type, and schema ID.
 *
 * @beta
 */
export type ResolveProjectionResult<
  TProjection extends string = string,
  TDocumentType extends string = string,
  TSchemaId extends string = string,
> = SanityProjectionResult<TProjection, TDocumentType, TSchemaId>
